import useIncentiveStore from '@/store/incentive'
import { IncentiveRewardInfo } from '@/types/incentive'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useTokenBalanceStore from '@cetus/stores/src/tokenBalance'
import { CheckBox, Icon } from '@cetus/ui-kit'
import { bnToAmount, d, formatCurrency, formatNumber, isAvailableObject } from '@cetus/utils'
import { extractStructTagFromType } from '@cetusprotocol/common-sdk'
import { Button, HStack, Text, VStack } from '@chakra-ui/react'
import dayjs from 'dayjs'
import { useEffect, useMemo, useState } from 'react'
import ConfirmModal from './ConfirmModal'
import RewardContent from './RewardContent'

export default function RewardTokenAndDuration() {
  const { incentiveApiPoolInfo, setIncentiveApiPoolInfo } = useIncentiveStore()
  const [isChecked, setIsChecked] = useState(false)
  const [isOpenModal, setIsOpenModal] = useState(false)
  const [rewardList, setRewardList] = useState<IncentiveRewardInfo[]>([{}])
  const [hasInitialized, setHasInitialized] = useState(false)
  const { tokenBalanceObj } = useTokenBalanceStore()

  // 结束时间 - 开始时间 要大于等于60分钟
  const isAllowSelect = (startTime: number, endTime: number): boolean => {
    if (!startTime || !endTime) return true
    return d(endTime)
      .minus(startTime)
      .gte(60 * 60 * 1000)
  }

  useEffect(() => {
    // 组件卸载时清空store的值
    return () => setIncentiveApiPoolInfo(undefined)
  }, [])

  useEffect(() => {
    if (!hasInitialized && incentiveApiPoolInfo?.displayTokenA) {
      setRewardList([
        {
          startTime: 0,
          endTime: 0,
          rewardCoin: incentiveApiPoolInfo.displayTokenA,
          rewardNum: '',
          releaseRate: '',
          startIsNow: false
        }
      ])
      setHasInitialized(true)
    }
  }, [incentiveApiPoolInfo, hasInitialized])

  // 更新奖励内容 startIsNow奖励是否现在开始 以提交交易的时间戳为准
  const updateReward = (index: number, key: string, value: any, startIsNow = false) => {
    setRewardList(prev =>
      prev.map((item, i) => {
        if (i !== index) return item
        let updatedItem = { ...item }

        if (key === 'rewardCoin') {
          updatedItem.rewardCoin = value
          updatedItem.rewardNum = ''
          updatedItem.releaseRate = ''
        } else if (key === 'startTime') {
          updatedItem.startIsNow = startIsNow
          updatedItem.startTime = value
          updatedItem.endTime = !isAllowSelect(value, item?.endTime || 0) ? 0 : item?.endTime
        } else {
          updatedItem[key] = value
        }

        if (updatedItem?.startTime && updatedItem?.endTime) {
          const duration = formatEpoch(updatedItem?.startTime, updatedItem?.endTime, true)
          console.log('🚀 ~ prev.map ~ duration:', updatedItem.rewardNum, duration)
          updatedItem.releaseRate = duration ? formatNumber(Number(updatedItem.rewardNum || 0) / Number(duration), item?.rewardCoin?.decimals) : '--'
        }

        return updatedItem
      })
    )
  }

  const defaultReward = () => ({
    startTime: '',
    endTime: '',
    rewardCoin: incentiveApiPoolInfo?.displayTokenA,
    rewardNum: '',
    releaseRate: '',
    startIsNow: false
  })

  // 添加奖励
  const addReward = () => {
    if (!incentiveApiPoolInfo?.displayTokenA) return
    setRewardList((prev: any) => [...prev, defaultReward()])
  }
  // 删除奖励
  const deleteReward = (index: number) => {
    setRewardList((prev: any) => {
      return prev.filter((_, i) => i !== index)
    })
  }
  // 判断余额
  const hasInsufficientBalance = useMemo(() => {
    if (!isAvailableObject(tokenBalanceObj)) return false

    const mergedMap: Record<string, { total: d; decimals: number }> = {}

    for (const item of rewardList) {
      const { rewardCoin, rewardNum } = item
      if (!rewardCoin?.coin_type || !rewardNum) continue

      const tag = extractStructTagFromType(rewardCoin.coin_type).full_address
      if (!mergedMap[tag]) {
        mergedMap[tag] = { total: d(0), decimals: rewardCoin.decimals ?? 9 }
      }
      mergedMap[tag].total = mergedMap[tag].total.plus(rewardNum)
    }

    return Object.entries(mergedMap).some(([addr, { total, decimals }]) => {
      const balance = tokenBalanceObj[addr]
      if (!balance) return true
      return total.gt(bnToAmount(balance.totalBalance, decimals))
    })
  }, [rewardList, tokenBalanceObj])

  // 判断奖励内容是否完整
  const isRewardValid = useMemo(() => {
    return (
      rewardList.length > 0 &&
      rewardList.every(item => item?.startTime && item?.endTime && item?.rewardCoin && item?.rewardNum && item?.releaseRate !== 0)
    )
  }, [rewardList])
  // 点击确认前判断时间是否超过开始时间 时间差应小于60s
  const isTimeValid = useMemo(() => {
    const now = dayjs().unix() // 当前时间戳（单位：秒）
    return rewardList.every(item => {
      // 如果开始时间为now 那么提交时间不会过期
      if (!item?.startIsNow && item?.startTime && item?.endTime) {
        const startTime = Number(item?.startTime)
        return d(now).minus(d(startTime).div(1000)).toNumber() < 60
      } else {
        return true
      }
    })
  }, [rewardList])

  const { getTokenAmountValue, fetchTokenPrices } = useTokenPrice()

  const totalAmount = useMemo(() => {
    const sum = rewardList.reduce((acc, item) => {
      const amount = getTokenAmountValue(item?.rewardCoin?.coin_type, item?.rewardNum)
      return acc.plus(amount)
    }, d(0))
    return formatCurrency(sum.toString(), 2)
  }, [rewardList])

  useEffect(() => {
    const coinTypes = rewardList.map(item => item?.rewardCoin?.coin_type).filter(Boolean)
    fetchTokenPrices(coinTypes)
  }, [rewardList])

  const whiteTokenList = useMemo(() => {
    return [{ ...incentiveApiPoolInfo?.displayTokenA }, { ...incentiveApiPoolInfo?.displayTokenB }]
  }, [incentiveApiPoolInfo])

  return (
    <VStack w="100%" align="flex-start" bg="card_bg" borderRadius="16px" p="32px">
      <HStack w="100%" justify="space-between">
        <VStack align="flex-start">
          <Text color="text_caption" fontSize="16px" fontWeight="500">
            Reward Token and Duration
          </Text>
          <Text fontSize="12px">Select reward tokens and define the release epoch for each</Text>
        </VStack>
        <Button
          onClick={addReward}
          borderRadius="8px"
          p={{ base: '0 8px', lg: '0 12px' }}
          h="36px"
          fontWeight="500"
          variant="outline"
          bg="primary_opacity.10"
          fontSize="12px"
          borderColor="transparent"
          isDisabled={rewardList?.length >= 5}
        >
          <Icon
            svgW="20px"
            svgH="20px"
            w="20px"
            h="20px"
            xlinkHref="#icon-icon_add"
            svgFill={rewardList?.length >= 5 ? 'primary_gray' : 'primary'}
            svgHover={rewardList?.length >= 5 ? 'primary_gray' : 'primary'}
          />
          Add Reward
        </Button>
      </HStack>

      <VStack w="100%" align="flex-start" mt="8px" gap="16px">
        {rewardList?.map((item, index) => (
          <RewardContent
            key={index}
            index={index}
            rewardListLength={rewardList?.length}
            rewardInfo={item}
            deleteReward={deleteReward}
            updateReward={updateReward}
            whiteTokenList={whiteTokenList}
          />
        ))}
      </VStack>

      <HStack
        bg="primary_opacity.10"
        borderRadius="8px"
        width="100%"
        p="12px"
        sx={{
          div: {
            svg: { fill: '#000 !important', w: '16px', h: '16px' }
          }
        }}
        cursor="pointer"
        onClick={() => setIsChecked(!isChecked)}
      >
        <CheckBox height="16px" width="16px" wrapStyle={{ bg: 'primary' }} checked={isChecked} onClick={() => {}} />
        <Text userSelect="none" lineHeight="16px" w="calc(100% - 24px)" fontSize="12px" color="primary">
          I acknowledge that once incentives are added, they can NOT be withdrawn under any circumstances
        </Text>
      </HStack>

      <Button
        w="100%"
        fontWeight="500"
        height="48px"
        isDisabled={!isRewardValid || !isChecked || hasInsufficientBalance || !isTimeValid}
        onClick={() => setIsOpenModal(true)}
      >
        {hasInsufficientBalance ? 'Insufficient Balance' : !isTimeValid ? 'Start time is invalid' : 'Incentivize'}
      </Button>

      <HStack w="100%" justify="space-between" mt="12px">
        <Text>Total Amount</Text>
        <Text>{totalAmount}</Text>
      </HStack>
      {isOpenModal && <ConfirmModal totalAmount={totalAmount} rewardList={rewardList} isOpen={isOpenModal} onClose={() => setIsOpenModal(false)} />}
    </VStack>
  )
}

// 格式化 Epoch 时间差
export function formatEpoch(startTime?: number, endTime?: number, returnHours?: boolean) {
  if (!startTime || !endTime) return returnHours ? undefined : ''
  const diffHours = dayjs(endTime).diff(dayjs(startTime), 'hour')
  const days = Math.floor(diffHours / 24)
  const hours = diffHours % 24
  return returnHours ? diffHours : `${days ? `${days} day${days > 1 ? 's' : ''} ` : ''}${hours} hour${hours !== 1 ? 's' : ''}`
}
