import useIncentiveStore from '@/store/incentive'
import useGetDlmmPools from '../pool/useGetDlmmPools'
import useGetPoolList from '../pool/useGetPoolList'

function useGetIncentivePoolInfo() {
  const { getDlmmPools } = useGetDlmmPools()
  const { getPoolList } = useGetPoolList()
  const { setIncentiveApiPoolInfo } = useIncentiveStore()

  const getIncentivePoolInfo = async (poolAddress: string, type: 'clmm' | 'dlmm' | string) => {
    if (!poolAddress) return
    let data: any

    if (type == 'clmm') {
      data = await getPoolList({ pool: poolAddress, display_all_pools: true })
    } else {
      data = await getDlmmPools({ pools: [poolAddress], display_all_pools: true })
    }
    console.log('🚀 ~ getPosPoolPoolData ~ data:', poolAddress, type, data)
    if (data) {
      setIncentiveApiPoolInfo(data?.list[0])
    }
  }
  return { getIncentivePoolInfo }
}
export default useGetIncentivePoolInfo
